sys_ui_action.script:
function requestBorrow() {
    var dueDate = prompt('Enter the due date for returning this equipment (YYYY-MM-DD):');
    if (dueDate) {
        var form = g_form.getFormElement();
        var existing = form.querySelector('input[name="sysparm_due_date"]');
        if (existing) existing.remove();
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'sysparm_due_date';
        input.value = dueDate;
        form.appendChild(input);
        gsftSubmit(null, form, 'request_to_borrow');
    }
}

if (typeof window == 'undefined') {
    var dueDate = request.getParameter('sysparm_due_date');
    var memberGr = new GlideRecord('x_828868_tool_le_0_members');
    memberGr.addQuery('user', gs.getUserID());
    memberGr.query();
    if (memberGr.next()) {
        var loanGr = new GlideRecord('x_828868_tool_le_0_loan_rec');
        loanGr.initialize();
        loanGr.setValue('equipment', current.getUniqueValue());
        loanGr.setValue('member', memberGr.getUniqueValue());
        loanGr.setValue('status', 'pending_approval');
        loanGr.setValue('due_date', dueDate);
        var loanId = loanGr.insert();
        gs.addInfoMessage('Your borrow request has been submitted for approval.');
        action.setRedirectURL(loanGr);
    } else {
        gs.addErrorMessage('You are not registered as a member.');
        action.setRedirectURL(current);
    }
}
